RSpec.describe Timekeeping::EntryWriteClient do
  let(:base_url) { "http://timekeeping.test" }
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) { example.run }
    end
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
  end

  # "Each forwarded call sends `Authorization` with a write `UserToken` minted for the context's actor and company (never for the target user), plus `Ownership-Generation`, an `Idempotency-Key` derived from request id, operation and entry id, and `X-Request-Id`."
  # A resend after a lost answer must carry the same key, or Timekeeping records the entry twice.
  it "replays one entry when the same forwarded create is sent twice under one request id" do
    context = Timekeeping::WriteContext.new(company:, actor: admin, actor_kind: "user", request_id: "req-resend-1")
    body = {
      "project_id" => project.id, "user_id" => admin.id, "work_date" => Date.current.iso8601, "duration" => 30.0,
      "note" => "sent twice", "source" => "manual", "source_metadata" => {}
    }

    first = described_class.new.create_entry(context:, generation: fake.generation, body:)
    second = described_class.new.create_entry(context:, generation: fake.generation, body:)

    expect(second["id"]).to eq(first["id"])
    keys = fake.requests.filter_map { |request| request[:headers]["Idempotency-Key"] if request[:method] == "POST" }
    expect(keys.size).to eq(2)
    expect(keys.uniq.size).to eq(1)
  end
end

RSpec.describe Timekeeping::EntryWriteClient, "forwarded requests" do
  let(:forwarding_base_url) { "http://timekeeping.test" }
  let(:forwarding_company) { create(:company) }
  let(:forwarding_admin) { forwarding_member(:admin) }
  let(:forwarding_colleague) { forwarding_member(:employee) }
  let(:forwarding_project) { create(:project, billable: true, client: create(:client, company: forwarding_company)) }
  let(:forwarding_entries_url) { "#{forwarding_base_url}/v1/companies/#{forwarding_company.id}/entries" }
  let(:forwarding_context) do
    Timekeeping::WriteContext.new(company: forwarding_company, actor: forwarding_admin, actor_kind: "user",
                                  request_id: "req-forwarding-1")
  end

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) { example.run }
  end

  def forwarding_member(role)
    create(:user).tap do |member|
      create(:employment, company: forwarding_company, user: member)
      member.add_role(role, forwarding_company)
    end
  end

  def forwarding_client
    described_class.new(base_url: forwarding_base_url)
  end

  def forwarding_create_body(user: forwarding_colleague)
    described_class.create_body(user:, project: forwarding_project,
                                attributes: { duration: 30.0, work_date: Date.current.iso8601, note: "forwarded" })
  end

  def forwarding_record_requests(method, url, status: 200, body: { "id" => 7 })
    requests = []
    stub_request(method, url).to_return do |request|
      requests << request
      { status:, body: body.to_json }
    end
    requests
  end

  it "mints the token for the actor and sends the target user only in the create body" do
    requests = forwarding_record_requests(:post, forwarding_entries_url, status: 201)

    forwarding_client.create_entry(context: forwarding_context, generation: 3, body: forwarding_create_body)

    sent = JSON.parse(requests.last.body)
    claims = Timekeeping::UserToken.verify(requests.last.headers["Authorization"].delete_prefix("Bearer "),
                                           public_key: timekeeping_key_pair.public_key)
    expect([claims.user_id, claims.company_id, claims.purpose]).to eq([forwarding_admin.id, forwarding_company.id, "write"])
    expect(sent).to include("user_id" => forwarding_colleague.id, "project_id" => forwarding_project.id,
                            "source" => "manual", "source_metadata" => {})
  end

  it "sends an update body with only the editable fields, never source, source_metadata or user_id" do
    requests = forwarding_record_requests(:patch, "#{forwarding_entries_url}/41")

    forwarding_client.update_entry(
      context: forwarding_context, generation: 3, entry_id: 41, version: 2,
      body: { "project_id" => forwarding_project.id, "note" => "edited", "source" => "manual",
              "source_metadata" => {}, "user_id" => forwarding_colleague.id }
    )

    expect(JSON.parse(requests.last.body)).to eq("project_id" => forwarding_project.id, "note" => "edited")
  end

  it "sends X-Request-Id, Ownership-Generation and Idempotency-Key on every write and If-Match on update and destroy" do
    creates = forwarding_record_requests(:post, forwarding_entries_url, status: 201)
    updates = forwarding_record_requests(:patch, "#{forwarding_entries_url}/41")
    destroys = forwarding_record_requests(:delete, "#{forwarding_entries_url}/41")

    forwarding_client.create_entry(context: forwarding_context, generation: 3, body: forwarding_create_body)
    forwarding_client.update_entry(context: forwarding_context, generation: 3, entry_id: 41, version: 2,
                                   body: { "note" => "edited" })
    forwarding_client.destroy_entry(context: forwarding_context, generation: 3, entry_id: 41, version: 5)

    sent = [creates, updates, destroys].map(&:last)
    expect(sent.map { |request| request.headers["X-Request-Id"] }).to all(eq("req-forwarding-1"))
    expect(sent.map { |request| request.headers["Ownership-Generation"] }).to all(eq("3"))
    expect(sent.map { |request| request.headers["Idempotency-Key"] }.uniq.size).to eq(3)
    expect(sent.map { |request| request.headers["If-Match"] }).to eq([nil, "2", "5"])
  end

  it "derives one key per request id, operation and entry id" do
    key = ->(**parts) { described_class.idempotency_key(request_id: "req-1", operation: "update", entry_id: 4, **parts) }

    expect(key.call).to eq(key.call)
    expect([key.call, key.call(operation: "destroy"), key.call(entry_id: 5), key.call(request_id: "req-2"),
            described_class.idempotency_key(request_id: "req-1", operation: "create")].uniq.size).to eq(5)
    expect(key.call).to match(/\A\h{8}-\h{4}-5\h{3}-\h{4}-\h{12}\z/)
  end

  it "maps each Timekeeping refusal to the monolith's own error" do
    answers = {
      [401, "unauthorized"] => Timekeeping::EntryWriteClient::Error,
      [403, "forbidden"] => Timekeeping::EntryWriteClient::Forbidden,
      [404, "not_found"] => ActiveRecord::RecordNotFound,
      [409, "stale_generation"] => Timekeeping::Gateway::StaleGeneration,
      [409, "version_conflict"] => Timekeeping::EntryWriteClient::Conflict,
      [422, "credential_in_body"] => Timekeeping::EntryWriteClient::Rejected,
      [500, "boom"] => Timekeeping::EntryWriteClient::Error
    }

    raised = answers.keys.map do |status, reason|
      stub_request(:delete, "#{forwarding_entries_url}/41").to_return(status:, body: { reason: }.to_json)
      forwarding_client.destroy_entry(context: forwarding_context, generation: 3, entry_id: 41, version: 1)
    rescue StandardError => error
      error.class
    end

    expect(raised).to eq(answers.values)
  end

  it "raises its own error for a timeout, a refused connection or an unreadable answer" do
    raised = [Net::OpenTimeout, Errno::ECONNREFUSED, { status: 201, body: "not json" }].map do |answer|
      stub = stub_request(:post, forwarding_entries_url)
      answer.is_a?(Hash) ? stub.to_return(answer) : stub.to_raise(answer)
      forwarding_client.create_entry(context: forwarding_context, generation: 3, body: forwarding_create_body)
    rescue StandardError => error
      error.class
    end

    expect(raised).to all(eq(Timekeeping::EntryWriteClient::Error))
  end

  it "refuses an actor who is not employed in the company and an unset signing key without sending anything" do
    stub_request(:post, forwarding_entries_url)
    outsider_context = Timekeeping::WriteContext.new(company: forwarding_company, actor: create(:user),
                                                     actor_kind: "user", request_id: "req-outsider")

    expect do
      forwarding_client.create_entry(context: outsider_context, generation: 3, body: forwarding_create_body)
    end.to raise_error(Timekeeping::EntryWriteClient::Forbidden)
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil) do
      expect do
        forwarding_client.create_entry(context: forwarding_context, generation: 3, body: forwarding_create_body)
      end.to raise_error(Timekeeping::EntryWriteClient::Error)
    end
    expect(WebMock).not_to have_requested(:post, forwarding_entries_url)
  end
end

RSpec.describe Timekeeping::EntryWriteClient, "edit fields" do
  # Timekeeping takes duration only as a JSON number, while a form post carries it as a string.
  it "sends a numeric duration string as a number and leaves other durations and absent fields as given" do
    expect(described_class.edit_fields("duration" => "30", "note" => "x")).to eq("duration" => 30.0, "note" => "x")
    expect(described_class.edit_fields(duration: "12.5")).to eq("duration" => 12.5)
    expect(described_class.edit_fields("duration" => "abc")).to eq("duration" => "abc")
    expect(described_class.edit_fields("duration" => 45)).to eq("duration" => 45)
    expect(described_class.edit_fields("note" => "only")).to eq("note" => "only")
  end

  it "builds a create body whose form-posted duration is a number" do
    user = build_stubbed(:user)
    project = build_stubbed(:project)

    body = described_class.create_body(user:, project:, attributes: { "duration" => "30", "work_date" => "2026-03-02" })

    expect(body["duration"]).to eq(30.0)
    expect(body).to include("project_id" => project.id, "user_id" => user.id, "source" => "manual")
  end
end

